import {EdgeSpring,edgeTargets,materialSettings,imageEffects,springParameters,motionTrail,easeMaterial} from './material-settings.js';
import {LiquidImage,getLiquidImage,getImageMotion} from './liquid-image.js';
export function prepareSkin(el){let skin=el.querySelector(':scope > .liquid-skin');if(!skin){skin=document.createElement('div');skin.className='liquid-skin';skin.setAttribute('aria-hidden','true');skin.innerHTML='<div class="material-reflection"></div>';el.prepend(skin);}el.classList.add('has-liquid-skin');return skin;}
// Read geometry in one batch. Only the independent skin is deformed; content never scales.
export class MotionMaterial {
 constructor(strength,reduced){this.strength=strength;this.reduced=reduced;this.items=new Map();this.raf=0;this.running=false;this.waiters=[];this.transientImages=new Map();}
 start(){this.waiters.splice(0).forEach(resolve=>resolve(false));this.snapSelector=null;cancelAnimationFrame(this.raf);this.running=true;if(this.reduced())return;this.raf=requestAnimationFrame(now=>{this.releaseDetachedImages();this.items.clear();for(const el of document.querySelectorAll('.surface:not(.flow-content)')){if(el.closest('.flow-shell')||el.closest('[data-retained-dormant]')||getComputedStyle(el).visibility==='hidden')continue;const rect=el.getBoundingClientRect();const skin=prepareSkin(el),r=parseFloat(getComputedStyle(el).borderRadius)||0,style=getComputedStyle(skin);const left=new EdgeSpring(),right=new EdgeSpring(),cornerLeft=new EdgeSpring(),cornerRight=new EdgeSpring(),reflectionSpring=new EdgeSpring();const reflectionStyle=getComputedStyle(skin.firstElementChild);if(reflectionStyle.transform!=='none')reflectionSpring.position=new DOMMatrixReadOnly(reflectionStyle.transform).m41;cornerLeft.position=(Number.isFinite(parseFloat(style.borderTopLeftRadius))?parseFloat(style.borderTopLeftRadius):r)-r;cornerRight.position=(Number.isFinite(parseFloat(style.borderTopRightRadius))?parseFloat(style.borderTopRightRadius):r)-r;if(style.transform!=='none'){const m=new DOMMatrixReadOnly(style.transform);left.position=m.m41-(m.m11-1)*rect.width/2;right.position=m.m41+(m.m11-1)*rect.width/2;}this.items.set(el,{skin,reflection:skin.firstElementChild,x:rect.left,y:rect.top,w:rect.width,h:rect.height,r,left,right,cornerLeft,cornerRight,reflectionSpring,visuals:[...el.querySelectorAll('.visual')],imageMotion:getImageMotion(el.querySelector('.visual')),glow:Number(skin.style.getPropertyValue('--skin-glow'))||0,vx:0,vy:0});}this.previous=now;this.tick(now);});}
 tick(now){const dt=Math.min(1.5,Math.max(.3,(now-this.previous)/16.667));this.previous=now;const reads=[];
 if(this.running){for(const [el,s] of this.items){if(el.isConnected)reads.push([s,el.getBoundingClientRect()]);}for(const [s,r] of reads){s.vx=(r.left-s.x)/(dt*16.667);s.vy=(r.top-s.y)/(dt*16.667);s.x=r.left;s.y=r.top;s.visible=r.right>0&&r.left<innerWidth&&r.bottom>0&&r.top<innerHeight;}}
 this.releaseDetachedImages();let remaining=0;for(const [el,s] of this.items){if(!el.isConnected||el.closest?.('[data-retained-dormant]')){s.skin.style.transform='';s.skin.style.borderRadius='';s.reflection.style.transform='';s.skin.style.removeProperty('--skin-glow');this.items.delete(el);continue;}if(!this.running&&this.snapSelector&&el.closest?.(this.snapSelector)){for(const spring of [s.left,s.right,s.cornerLeft,s.cornerRight,s.reflectionSpring]){spring.position=0;spring.velocity=0;}s.imageMotion.x=0;s.imageMotion.y=0;}const [leftTarget,rightTarget]=this.running?edgeTargets(s.vx,materialSettings):[0,0];const {k,damper}=springParameters(materialSettings);
 const left=s.left.step(leftTarget*this.strength(),k/(1+materialSettings.lag*.013),damper,dt),right=s.right.step(rightTarget*this.strength(),k,damper,dt);
 const width=Math.max(s.w*.7,s.w+right-left),sx=width/s.w,compression=Math.min(.05,Math.abs(right-left)/s.w*.18),center=(left+right)*.5;
 s.skin.style.transform=`translate3d(${center.toFixed(2)}px,0,0) scale(${sx.toFixed(4)},${(1-compression).toFixed(4)})`;
 const direction=Math.sign(s.vx||right-left),energy=Math.min(1,Math.abs(right-left)/65);const lead=s.r*(1+energy*.45),tail=s.r*(1-energy*.3);
 const cl=s.cornerLeft.step(this.running?(direction>=0?tail-s.r:lead-s.r):0,k,damper,dt),cr=s.cornerRight.step(this.running?(direction>=0?lead-s.r:tail-s.r):0,k,damper,dt);s.skin.style.borderRadius=`${s.r+cl}px ${s.r+cr}px ${s.r+cr}px ${s.r+cl}px`;
 const reflection=s.reflectionSpring.step(this.running?Math.max(-35,Math.min(35,s.vx*10)):0,k*.65,damper,dt);s.reflection.style.transform=`translate3d(${reflection.toFixed(2)}px,0,0)`;const trail=this.running&&imageEffects.blur?motionTrail(s.vx,s.vy,materialSettings.motionBlur):{x:0,y:0};s.imageMotion.x=easeMaterial(s.imageMotion.x,trail.x,dt);s.imageMotion.y=easeMaterial(s.imageMotion.y,trail.y,dt);for(const visual of s.visuals){let image=getLiquidImage(visual)||this.transientImages.get(visual);if(!image&&s.visible&&Math.hypot(s.imageMotion.x,s.imageMotion.y)>.02){image=new LiquidImage(visual,this.strength);this.transientImages.set(visual,image);}image?.setMotion(s.visible?s.imageMotion.x:0,s.visible?s.imageMotion.y:0);}
 s.glow=easeMaterial(s.glow,energy*materialSettings.glow/100,dt);s.skin.style.setProperty('--skin-glow',String(s.glow));remaining=Math.max(remaining,Math.abs(left)+Math.abs(right)+Math.abs(s.left.velocity)+Math.abs(s.right.velocity)+Math.abs(s.cornerLeft.position)+Math.abs(s.cornerRight.position)+Math.abs(s.cornerLeft.velocity)+Math.abs(s.cornerRight.velocity)+Math.abs(s.reflectionSpring.position)+Math.abs(s.reflectionSpring.velocity)+Math.abs(s.imageMotion.x)+Math.abs(s.imageMotion.y)+s.glow);
 }
 if(this.running||remaining>.08){this.raf=requestAnimationFrame(t=>this.tick(t));}else{for(const s of this.items.values()){s.skin.style.transform='';s.skin.style.borderRadius='';s.reflection.style.transform='';for(const visual of s.visuals)getLiquidImage(visual)?.setMotion(0,0);s.skin.style.removeProperty('--skin-glow');}this.items.clear();for(const image of this.transientImages.values())image.destroy();this.transientImages.clear();this.raf=0;this.snapSelector=null;this.waiters.splice(0).forEach(resolve=>resolve(true));}
 }
 releaseDetachedImages(){for(const [el,image] of this.transientImages){if(!el.isConnected){image.destroy();this.transientImages.delete(el);}}}
 reset(){
  cancelAnimationFrame(this.raf);this.raf=0;this.running=false;this.snapSelector=null;
  for(const s of this.items.values()){s.skin.style.transform='';s.skin.style.borderRadius='';s.reflection.style.transform='';s.skin.style.removeProperty('--skin-glow');for(const visual of s.visuals)getLiquidImage(visual)?.setMotion(0,0);}
  this.items.clear();for(const image of this.transientImages.values())image.destroy();this.transientImages.clear();this.waiters.splice(0).forEach(resolve=>resolve(true));
 }
 stop({snapSelector=null}={}){this.running=false;this.snapSelector=snapSelector;if(!this.raf){this.snapSelector=null;return Promise.resolve(true);}return new Promise(resolve=>this.waiters.push(resolve));}
}
